import{_ as r,a0 as l,w as p,s as o,I as s,a1 as n,A as t,x as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"如何在 Fedora 30 Server 上安装 LEMP（Linux、Nginx、MariaDB、PHP） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora 30 Server 上安装 LEMP（Linux、Nginx、MariaDB、PHP） | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora 30 Server 上安装 LEMP（Linux、Nginx、MariaDB、PHP） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora 30 Server 上安装 LEMP（Linux、Nginx、MariaDB、PHP） | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20190602 How to Install LEMP (Linux, Nginx, MariaDB, PHP) on Fedora 30 Server","title":"如何在 Fedora 30 Server 上安装 LEMP（Linux、Nginx、MariaDB、PHP）","tag":"201912","desc":""},"relativePath":"201912/20190602 How to Install LEMP (Linux, Nginx, MariaDB, PHP) on Fedora 30 Server.md","filePath":"[post].md"}'),h={name:"201912/20190602 How to Install LEMP (Linux, Nginx, MariaDB, PHP) on Fedora 30 Server.md"};function g(u,a,c,m,b,k){const e=l("Link");return p(),o("div",null,[s("p",null,[n(e,{href:"collector:",title:"lujun9972"},{default:t(()=>[...a[0]||(a[0]=[i("#",-1)])]),_:1}),a[5]||(a[5]=i(": subject: (How to Install LEMP (Linux, Nginx, MariaDB, PHP) on Fedora 30 Server) ",-1)),n(e,{href:"collector:",title:"lujun9972"},{default:t(()=>[...a[1]||(a[1]=[i("#",-1)])]),_:1}),a[6]||(a[6]=i(": via: (",-1)),n(e,{href:"https://www.linuxtechi.com/install-lemp-stack-fedora-30-server/"},{default:t(()=>[...a[2]||(a[2]=[i("https://www.linuxtechi.com/install-lemp-stack-fedora-30-server/",-1)])]),_:1}),a[7]||(a[7]=i(") ",-1)),n(e,{href:"collector:",title:"lujun9972"},{default:t(()=>[...a[3]||(a[3]=[i("#",-1)])]),_:1}),a[8]||(a[8]=i(": author: (Pradeep Kumar ",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...a[4]||(a[4]=[i("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),a[9]||(a[9]=i(")",-1))]),a[28]||(a[28]=s("h1",{id:"如何在-fedora-30-server-上安装-lemp-linux、nginx、mariadb、php",tabindex:"-1"},[i("如何在 Fedora 30 Server 上安装 LEMP（Linux、Nginx、MariaDB、PHP） "),s("a",{class:"header-anchor",href:"#如何在-fedora-30-server-上安装-lemp-linux、nginx、mariadb、php","aria-label":"Permalink to “如何在 Fedora 30 Server 上安装 LEMP（Linux、Nginx、MariaDB、PHP）”"},"​")],-1)),a[29]||(a[29]=s("p",null,[i("在这篇文章中，我们将看看如何在 Fedora 30 Server 上安装 "),s("strong",null,"LEMP"),i(" 。LEMP 代表：")],-1)),a[30]||(a[30]=s("ul",null,[s("li",null,"L -> Linux"),s("li",null,"E -> Nginx"),s("li",null,"M -> Maria DB"),s("li",null,"P -> PHP")],-1)),s("p",null,[a[11]||(a[11]=i("我假设 ",-1)),n(e,{href:"https://www.linuxtechi.com/fedora-30-workstation-installation-guide/"},{default:t(()=>[...a[10]||(a[10]=[i("Fedora 30",-1)])]),_:1}),a[12]||(a[12]=i(" 已经安装在你的电脑系统上。",-1))]),a[31]||(a[31]=d(`<p><img src="https://img.linux.net.cn/data/attachment/album/201912/01/103537wil7hd36dhcxdh03.jpg" alt=""></p><p>LEMP 是一组强大的软件设置集合，它安装在一个 Linux 服务器上以帮助使用流行的开发平台来构建网站，LEMP 是 LAMP 的一个变种，在其中不是 Apache ，而是使用 EngineX（Nginx），此外，使用 MariaDB 代替 MySQL。这篇入门指南是一个安装 Nginx、Maria DB 和 PHP 的独立指南的作品集合。</p><h3 id="在-fedora-30-server-上安装-nginx、php-7-3-和-php-fpm" tabindex="-1">在 Fedora 30 Server 上安装 Nginx、PHP 7.3 和 PHP-FPM <a class="header-anchor" href="#在-fedora-30-server-上安装-nginx、php-7-3-和-php-fpm" aria-label="Permalink to “在 Fedora 30 Server 上安装 Nginx、PHP 7.3 和 PHP-FPM”">​</a></h3><p>让我们看看如何在 Fedora 30 Server 上安装 Nginx 和 PHP 以及 PHP FPM。</p><h4 id="步骤-1-切换到-root-用户" tabindex="-1">步骤 1) 切换到 root 用户 <a class="header-anchor" href="#步骤-1-切换到-root-用户" aria-label="Permalink to “步骤 1) 切换到 root 用户”">​</a></h4><p>在系统上安装 Nginx 的第一步是切换到 root 用户。使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~]$ sudo -i</span></span>
<span class="line"><span>[sudo] password for pkumar:</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步骤-2-使用-dnf-命令安装-nginx、php-7-3-和-php-fpm" tabindex="-1">步骤 2) 使用 dnf 命令安装 Nginx、PHP 7.3 和 PHP FPM <a class="header-anchor" href="#步骤-2-使用-dnf-命令安装-nginx、php-7-3-和-php-fpm" aria-label="Permalink to “步骤 2) 使用 dnf 命令安装 Nginx、PHP 7.3 和 PHP FPM”">​</a></h4><p>使用下面的 <code>dnf</code> 命令安装 Nginx：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install nginx php php-fpm php-common -y</span></span></code></pre></div><h4 id="步骤-3-安装额外的-php-模块" tabindex="-1">步骤 3) 安装额外的 PHP 模块 <a class="header-anchor" href="#步骤-3-安装额外的-php-模块" aria-label="Permalink to “步骤 3) 安装额外的 PHP 模块”">​</a></h4><p>PHP 的默认安装仅自带基本模块和最需要的模块，如果你需要额外的模块，像 PHP 支持的 GD、XML、命令行接口、Zend OPCache 功能等等，你总是能够选择你的软件包，并一次性安装所有的东西。查看下面的示例命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# sudo dnf install php-opcache php-pecl-apcu php-cli php-pear php-pdo php-pecl-mongodb php-pecl-redis php-pecl-memcache php-pecl-memcached php-gd php-mbstring php-mcrypt php-xml -y</span></span></code></pre></div><h4 id="步骤-4-开始-启用-nginx-和-php-fpm-服务" tabindex="-1">步骤 4) 开始 &amp; 启用 Nginx 和 PHP-fpm 服务 <a class="header-anchor" href="#步骤-4-开始-启用-nginx-和-php-fpm-服务" aria-label="Permalink to “步骤 4) 开始 &amp; 启用 Nginx 和 PHP-fpm 服务”">​</a></h4><p>使用下面的命令来开始并启用 Nginx 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl start nginx &amp;&amp; systemctl enable nginx</span></span>
<span class="line"><span>Created symlink /etc/systemd/system/multi-user.target.wants/nginx.service → /usr/lib/systemd/system/nginx.service.</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>使用下面的命令来开始并启用 PHP-FPM 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl start php-fpm &amp;&amp; systemctl enable php-fpm</span></span>
<span class="line"><span>Created symlink /etc/systemd/system/multi-user.target.wants/php-fpm.service → /usr/lib/systemd/system/php-fpm.service.</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步骤-5-核实-nginx-web-服务-和-php-安装" tabindex="-1">步骤 5) 核实 Nginx (Web 服务) 和 PHP 安装 <a class="header-anchor" href="#步骤-5-核实-nginx-web-服务-和-php-安装" aria-label="Permalink to “步骤 5) 核实 Nginx (Web 服务) 和 PHP 安装”">​</a></h4><p>注意：假使操作系统防火墙是启用的，并运行在你的 Fedora 30 系统上，那么使用下面的命令来准许 80 和 443 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# firewall-cmd --permanent --add-service=http</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span>
<span class="line"><span>[root@linuxtechi ~]# firewall-cmd --permanent --add-service=https</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]# firewall-cmd --reload</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>打开网页浏览器，输入下面的 URL： <code>http://&lt;Your-Server-IP&gt;</code> 。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Test-Page-HTTP-Server-Fedora-30.jpg" alt="Test-Page-HTTP-Server-Fedora-30"></p><p>上面的屏幕证实 Nginx 已经成功地安装。</p><p>现在，让我们核实 PHP 安装，使用下面的命令创建一个测试 php 页（<code>info.php</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# echo &quot;&lt;?php phpinfo(); ?&gt;&quot; &gt; /usr/share/nginx/html/info.php</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>在网页浏览器中输入下面的 URL， <code>http://&lt;Your-Server-IP&gt;/info.php</code></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Php-info-page-fedora30.jpg" alt="Php-info-page-fedora30"></p><p>上面的页面验证 PHP 7.3.5 已经被成功地安装。现在，让我们安装 MariaDB 数据库服务器。</p><h3 id="在-fedora-30-上安装-mariadb" tabindex="-1">在 Fedora 30 上安装 MariaDB <a class="header-anchor" href="#在-fedora-30-上安装-mariadb" aria-label="Permalink to “在 Fedora 30 上安装 MariaDB”">​</a></h3><p>MariaDB 是 MySQL 数据库的一个极好的替代品，因为它的工作方式与 MySQL 非常类似，并且兼容性也与 MySQL 一致。让我们看看在 Fedora 30 Server 上安装 MariaDB 的步骤。</p><h4 id="步骤-1-切换到-root-用户-1" tabindex="-1">步骤 1) 切换到 root 用户 <a class="header-anchor" href="#步骤-1-切换到-root-用户-1" aria-label="Permalink to “步骤 1) 切换到 root 用户”">​</a></h4><p>在系统上安装 MariaDB 的第一步是切换到 root 用户，或者你可以使用有 root 权限的本地用户。使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# sudo -i</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步骤-2-使用-dnf-命令安装-mariadb-10-3-的最新版本" tabindex="-1">步骤 2) 使用 dnf 命令安装 MariaDB（10.3）的最新版本 <a class="header-anchor" href="#步骤-2-使用-dnf-命令安装-mariadb-10-3-的最新版本" aria-label="Permalink to “步骤 2) 使用 dnf 命令安装 MariaDB（10.3）的最新版本”">​</a></h4><p>在 Fedora 30 Server 上使用下面的命令来安装 MariaDB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install mariadb-server -y</span></span></code></pre></div><h4 id="步骤-3-开启并启用-mariadb-服务" tabindex="-1">步骤 3) 开启并启用 MariaDB 服务 <a class="header-anchor" href="#步骤-3-开启并启用-mariadb-服务" aria-label="Permalink to “步骤 3) 开启并启用 MariaDB 服务”">​</a></h4><p>在步骤 2 中成功地安装 MariaDB 后，接下来的步骤是开启 MariaDB 服务。使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl start mariadb.service ; systemctl enable mariadb.service</span></span></code></pre></div><h4 id="步骤-4-保护安装好的-mariadb" tabindex="-1">步骤 4) 保护安装好的 MariaDB <a class="header-anchor" href="#步骤-4-保护安装好的-mariadb" aria-label="Permalink to “步骤 4) 保护安装好的 MariaDB”">​</a></h4><p>当我们安装 MariaDB 服务器时，因为默认情况下没有 root 密码，在数据库中也会创建匿名用户。因此，要保护安装好的 MariaDB，运行下面的 <code>mysql_secure_installation</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# mysql_secure_installation</span></span></code></pre></div><p>接下来你将被提示一些问题，仅回答下面展示的问题：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Secure-MariaDB-Installation-Part1.jpg" alt="Secure-MariaDB-Installation-Part1"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Secure-MariaDB-Installation-Part2.jpg" alt="Secure-MariaDB-Installation-Part2"></p><h4 id="步骤-5-测试-mariadb-安装" tabindex="-1">步骤 5) 测试 MariaDB 安装 <a class="header-anchor" href="#步骤-5-测试-mariadb-安装" aria-label="Permalink to “步骤 5) 测试 MariaDB 安装”">​</a></h4><p>在你安装后，你总是能够测试是否 MariaDB 被成功地安装在 Fedora 30 Server 上。使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# mysql -u root -p</span></span>
<span class="line"><span>Enter password:</span></span></code></pre></div><p>接下来，你将被提示一个密码。输入在保护安装好的 MariaDB 期间你设置的密码，接下来你可以看到 MariaDB 欢迎屏幕。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Welcome to the MariaDB monitor.  Commands end with ; or \\g.</span></span>
<span class="line"><span>Your MariaDB connection id is 17</span></span>
<span class="line"><span>Server version: 10.3.12-MariaDB MariaDB Server</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Copyright (c) 2000, 2018, Oracle, MariaDB Corporation Ab and others.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Type &#39;help;&#39; or &#39;\\h&#39; for help. Type &#39;\\c&#39; to clear the current input statement.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MariaDB [(none)]&gt;</span></span></code></pre></div><p>最后，我们已经在你的 Fedora 30 Server 上成功地完成安装 LEMP（Linux、Nginx、MariaDB 和 PHP）的所有工作。请在下面的反馈部分发布你的评论和建议，我们将尽快在后面回应。</p><hr>`,53)),s("p",null,[a[14]||(a[14]=i("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/install-lemp-stack-fedora-30-server/"},{default:t(()=>[...a[13]||(a[13]=[i("https://www.linuxtechi.com/install-lemp-stack-fedora-30-server/",-1)])]),_:1})]),s("p",null,[a[19]||(a[19]=i("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...a[15]||(a[15]=[i("Pradeep Kumar",-1)])]),_:1}),a[20]||(a[20]=i(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[16]||(a[16]=[i("lujun9972",-1)])]),_:1}),a[21]||(a[21]=i(" 译者：",-1)),n(e,{href:"https://github.com/robsean"},{default:t(()=>[...a[17]||(a[17]=[i("robsean",-1)])]),_:1}),a[22]||(a[22]=i(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...a[18]||(a[18]=[i("wxy",-1)])]),_:1})]),s("p",null,[a[25]||(a[25]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[23]||(a[23]=[i("LCTT",-1)])]),_:1}),a[26]||(a[26]=i(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...a[24]||(a[24]=[i("Linux中国",-1)])]),_:1}),a[27]||(a[27]=i(" 荣誉推出",-1))])])}const M=r(h,[["render",g]]);export{P as __pageData,M as default};
